		for(int j=1;j<=n;j++){
			if(i==j){
				map[i][j]=0;
			}else if(x[j]>=x[i]&&y[j]>=y[i])
				map[i][j]=abs(x[i]-x[j])+abs(y[i]-y[j])-1;
